import{_ as e,c as n,o as a,j as s,Y as i,t as r}from"./chunks/framework.BNTND4LZ.js";const q=JSON.parse('{"title":"gitprotocol-common | x-cmd man (git man5) | Things common to various protocols","titleTemplate":false,"description":"x-cmd man (git man5 Manual Page) | gitprotocol-common - Things common to various protocols","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"gitprotocol-common | x-cmd man (git man5) | Things common to various protocols"}],["meta",{"name":"og:description","content":"x-cmd man (git man5 Manual Page) | gitprotocol-common - Things common to various protocols"}]]},"headers":[],"params":{"isMan":true,"man":"gitprotocol-common","category":"git man5","desc":"Things common to various protocols"},"relativePath":"git/man5/gitprotocol-common.md","filePath":"git/man5/[man].md"}'),l={name:"git/man5/gitprotocol-common.md"},c={class:"visually-hidden"};function p(o,t,h,u,d,m){return a(),n("div",null,[s("h1",c,r(o.$params.man),1),t[0]||(t[0]=i(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>gitprotocol-common - Things common to various protocols</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">over-the-wire-protocol</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This document sets defines things common to various over-the-wire protocols and file formats used in Git.</p><h2 id="abnf-notation" tabindex="-1">ABNF NOTATION <a class="header-anchor" href="#abnf-notation" aria-label="Permalink to &quot;ABNF NOTATION&quot;">​</a></h2><p>ABNF notation as described by RFC 5234 is used within the protocol documents, except the following replacement core rules are used:</p><blockquote><pre><code>  HEXDIG    =  DIGIT / &quot;a&quot; / &quot;b&quot; / &quot;c&quot; / &quot;d&quot; / &quot;e&quot; / &quot;f&quot;
</code></pre></blockquote><p>We also define the following common rules:</p><blockquote><pre><code>  NUL       =  %x00
  zero-id   =  40*&quot;0&quot;
  obj-id    =  40*(HEXDIGIT)

  refname  =  &quot;HEAD&quot;
  refname /=  &quot;refs/&quot; &lt;see discussion below&gt;
</code></pre></blockquote><p>A refname is a hierarchical octet string beginning with &quot;refs/&quot; and not violating the <em>git-check-ref-format</em> command&#39;s validation rules. More specifically, they:</p><blockquote><p>1.</p><p>They can include slash <strong>/</strong> for hierarchical (directory) grouping, but no slash-separated component can begin with a dot <strong>.</strong>.</p></blockquote><blockquote><p>2.</p><p>They must contain at least one <strong>/</strong>. This enforces the presence of a category like <strong>heads/</strong>, <strong>tags/</strong> etc. but the actual names are not restricted.</p></blockquote><blockquote><p>3.</p><p>They cannot have two consecutive dots <strong>..</strong> anywhere.</p></blockquote><blockquote><p>4.</p><p>They cannot have ASCII control characters (i.e. bytes whose values are lower than \\040, or \\177 <strong>DEL</strong>), space, tilde <strong>~</strong>, caret <strong>^</strong>, colon <strong>:</strong>, question-mark <strong>?</strong>, asterisk *<em>*</em> *, or open bracket <strong>[</strong> anywhere.</p></blockquote><blockquote><p>5.</p><p>They cannot end with a slash <strong>/</strong> or a dot <strong>.</strong>.</p></blockquote><blockquote><p>6.</p><p>They cannot end with the sequence <strong>.lock</strong>.</p></blockquote><blockquote><p>7.</p><p>They cannot contain a sequence <strong>@{</strong>.</p></blockquote><blockquote><p>8.</p><p>They cannot contain a <strong>\\\\</strong>.</p></blockquote><h2 id="pkt-line-format" tabindex="-1">PKT-LINE FORMAT <a class="header-anchor" href="#pkt-line-format" aria-label="Permalink to &quot;PKT-LINE FORMAT&quot;">​</a></h2><p>Much (but not all) of the payload is described around pkt-lines.</p><p>A pkt-line is a variable length binary string. The first four bytes of the line, the pkt-len, indicates the total length of the line, in hexadecimal. The pkt-len includes the 4 bytes used to contain the length&#39;s hexadecimal representation.</p><p>A pkt-line MAY contain binary data, so implementors MUST ensure pkt-line parsing/formatting routines are 8-bit clean.</p><p>A non-binary line SHOULD BE terminated by an LF, which if present MUST be included in the total length. Receivers MUST treat pkt-lines with non-binary data the same whether or not they contain the trailing LF (stripping the LF if present, and not complaining when it is missing).</p><p>The maximum length of a pkt-line&#39;s data component is 65516 bytes. Implementations MUST NOT send pkt-line whose length exceeds 65520 (65516 bytes of payload + 4 bytes of length data).</p><p>Implementations SHOULD NOT send an empty pkt-line (&quot;0004&quot;).</p><p>A pkt-line with a length field of 0 (&quot;0000&quot;), called a flush-pkt, is a special case and MUST be handled differently than an empty pkt-line (&quot;0004&quot;).</p><blockquote><pre><code>  pkt-line     =  data-pkt / flush-pkt

  data-pkt     =  pkt-len pkt-payload
  pkt-len      =  4*(HEXDIG)
  pkt-payload  =  (pkt-len - 4)*(OCTET)

  flush-pkt    = &quot;0000&quot;
</code></pre></blockquote><p>Examples (as C-style strings):</p><blockquote><pre><code>  pkt-line          actual value
  ---------------------------------
  &quot;0006a\\n&quot;         &quot;a\\n&quot;
  &quot;0005a&quot;           &quot;a&quot;
  &quot;000bfoobar\\n&quot;    &quot;foobar\\n&quot;
  &quot;0004&quot;            &quot;&quot;
</code></pre></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,33))])}const k=e(l,[["render",p]]);export{q as __pageData,k as default};
